=== src/service/ReconcileService.java
     1	package service;
     2	
     3	import domain.DailyLine;
     4	import domain.StatementRow;
     5	
     6	import java.time.LocalDate;
     7	import java.util.ArrayList;
     8	import java.util.HashMap;
     9	import java.util.List;
    10	import java.util.Map;
    11	
    12	/** Compares our daily lines with the partners' statements. */
    13	public class ReconcileService {
    14	
    15	    /** Difference between our settlement and the partner's statement for a date/partner. */
    16	    public record Mismatch(LocalDate date, String partnerId, String field, long ours, long theirs) {
    17	        public long diff() { return ours - theirs; }
    18	    }
    19	
    20	    public List<Mismatch> compare(List<DailyLine> ours, List<StatementRow> theirs) {
    21	        Map<String, DailyLine> mine = new HashMap<>();
    22	        for (DailyLine l : ours) mine.put(key(l.date(), l.partnerId()), l);
    23	        List<Mismatch> out = new ArrayList<>();
    24	        for (StatementRow r : theirs) {
    25	            DailyLine l = mine.remove(key(r.date(), r.partnerId()));
    26	            if (l == null) {
    27	                out.add(new Mismatch(r.date(), r.partnerId(), "missing", 0, r.grossKrw()));
    28	                continue;
    29	            }
    30	            if (l.count() != r.count()) out.add(new Mismatch(r.date(), r.partnerId(), "count", l.count(), r.count()));
    31	            if (l.grossKrw() != r.grossKrw()) out.add(new Mismatch(r.date(), r.partnerId(), "gross", l.grossKrw(), r.grossKrw()));
    32	        }
    33	        for (DailyLine l : mine.values()) {
    34	            out.add(new Mismatch(l.date(), l.partnerId(), "unexpected", l.grossKrw(), 0));
    35	        }
    36	        out.sort((a, b) -> a.date().equals(b.date()) ? a.partnerId().compareTo(b.partnerId()) : a.date().compareTo(b.date()));
    37	        return out;
    38	    }
    39	
    40	    private static String key(LocalDate d, String partner) {
    41	        return d + "|" + partner;
    42	    }
    43	}
=== src/infra/FxqClient.java
     1	package infra;
     2	
     3	import domain.FxQuote;
     4	
     5	import java.io.IOException;
     6	import java.io.InputStream;
     7	import java.math.BigDecimal;
     8	import java.nio.charset.StandardCharsets;
     9	import java.nio.file.Path;
    10	import java.time.LocalDate;
    11	import java.util.ArrayList;
    12	import java.util.List;
    13	import java.util.concurrent.TimeUnit;
    14	
    15	/** Thin wrapper around the vendor quote CLI. One process per call. */
    16	public class FxqClient {
    17	    private final Path bin;
    18	    private final long timeoutSeconds;
    19	
    20	    public FxqClient(Path bin, long timeoutSeconds) {
    21	        this.bin = bin;
    22	        this.timeoutSeconds = timeoutSeconds;
    23	    }
    24	
    25	    /** Raw stdout line for {@code fxq rate PAIR DATE}. */
    26	    public String rate(String pair, LocalDate date) {
    27	        List<String> cmd = new ArrayList<>();
    28	        cmd.add(bin.toString());
    29	        cmd.add("rate");
    30	        cmd.add(pair);
    31	        cmd.add(date.toString());
    32	        return run(cmd);
    33	    }
    34	
    35	    /** Parses one quote line: {@code PAIR YYYY-MM-DD RATE ...}. */
    36	    public static FxQuote parse(String line) {
    37	        String[] t = line.trim().split("\\s+");
    38	        if (t.length < 3) {
    39	            throw new IllegalArgumentException("unexpected quote line: " + line);
    40	        }
    41	        return new FxQuote(t[0], LocalDate.parse(t[1]), new BigDecimal(t[2]));
    42	    }
    43	
    44	    private String run(List<String> cmd) {
    45	        try {
    46	            Process p = new ProcessBuilder(cmd).start();
    47	            byte[] out;
    48	            byte[] err;
    49	            try (InputStream o = p.getInputStream(); InputStream e = p.getErrorStream()) {
    50	                out = o.readAllBytes();
    51	                err = e.readAllBytes();
    52	            }
    53	            if (!p.waitFor(timeoutSeconds, TimeUnit.SECONDS)) {
    54	                p.destroyForcibly();
    55	                throw new FxqException("timeout", cmd);
    56	            }
    57	            if (p.exitValue() != 0) {
    58	                throw new FxqException(new String(err, StandardCharsets.UTF_8).trim(), cmd);
    59	            }
    60	            String line = new String(out, StandardCharsets.UTF_8).trim();
    61	            if (line.isEmpty()) throw new FxqException("empty output", cmd);
    62	            return line;
    63	        } catch (IOException e) {
    64	            throw new FxqException("exec failed: " + e.getMessage(), cmd);
    65	        } catch (InterruptedException e) {
    66	            Thread.currentThread().interrupt();
    67	            throw new FxqException("interrupted", cmd);
    68	        }
    69	    }
    70	
    71	    public static class FxqException extends RuntimeException {
    72	        public FxqException(String code, List<String> cmd) {
    73	            super("fxq failed [" + code + "]: " + String.join(" ", cmd));
    74	        }
    75	    }
    76	}
