     1	package service;
     2	
     3	import java.util.Map;
     4	
     5	/** Maps a card currency to the vendor pair code and its quotation unit. */
     6	public final class CurrencyPairs {
     7	    private static final Map<String, Integer> UNITS = Map.of("USD", 1, "EUR", 1, "JPY", 100, "CNY", 1);
     8	
     9	    private CurrencyPairs() {}
    10	
    11	    public static String pairOf(String currency) {
    12	        requireSupported(currency);
    13	        return currency + "KRW";
    14	    }
    15	
    16	    /** JPY is quoted per 100 yen. */
    17	    public static int unitOf(String currency) {
    18	        requireSupported(currency);
    19	        return UNITS.get(currency);
    20	    }
    21	
    22	    public static boolean supported(String currency) {
    23	        return UNITS.containsKey(currency);
    24	    }
    25	
    26	    private static void requireSupported(String currency) {
    27	        if (!supported(currency)) throw new IllegalArgumentException("unsupported currency " + currency);
    28	    }
    29	}

