    10	import java.util.Properties;
    11	
    12	/** Loads conf/app.properties; system properties and SETTLE_* environment variables override. */
    13	public final class AppConfig {
    14	    private final Properties props = new Properties();
    15	
    16	    private AppConfig() {}
    17	
    18	    public static AppConfig load() {
    19	        return load(Path.of("conf", "app.properties"));
    20	    }
    21	
    22	    public static AppConfig load(Path file) {
    23	        AppConfig cfg = new AppConfig();
    24	        try (InputStream in = Files.newInputStream(file)) {
    25	            cfg.props.load(in);
    26	        } catch (IOException e) {
    27	            throw new IllegalStateException("cannot read config " + file, e);
    28	        }
    29	        return cfg;
    30	    }
    31	
    32	    public String get(String key) {
    33	        String sys = System.getProperty("settle." + key);
    34	        if (sys != null && !sys.isBlank()) return sys.trim();
    35	        String env = System.getenv("SETTLE_" + key.toUpperCase().replace('.', '_'));
    36	        if (env != null && !env.isBlank()) return env.trim();
    37	        String v = props.getProperty(key);
    38	        if (v == null) throw new IllegalStateException("missing config key " + key);
    39	        return v.trim();
    40	    }
    41	
    42	    public Path fxqBin() { return Path.of(get("fxq.bin")); }
    43	
    44	    public long fxqTimeoutSeconds() { return Long.parseLong(get("fxq.timeoutSeconds")); }
    45	
    46	    public Path dataDir() { return Path.of(get("data.dir")); }
    47	
    48	    public ZoneId businessZone() { return ZoneId.of(get("business.zone")); }
    49	
    50	    public List<String> boardCurrencies() {
    51	        return Arrays.stream(get("board.currencies").split(",")).map(String::trim).filter(s -> !s.isEmpty()).toList();
    52	    }
    53	}

