    out=subprocess.run([FX,'rate',pair,d,'--src',str(src)],capture_output=True,text=True).stdout.split()
    return Decimal(out[2]), (len(out)>3)
stmt={}
for r in csv.DictReader(l for l in open(R+'fixtures/partner-statement.csv',encoding='utf-8') if not l.startswith('#')):
    stmt[(r['date'],r['partner_id'])]=(int(r['count']),int(r['gross_krw']))
txn=[]
for r in csv.DictReader(l for l in open(R+'fixtures/transactions.csv',encoding='utf-8') if not l.startswith('#')):
    t=dt.datetime.fromisoformat(r['approved_at'].replace('Z','+00:00')).astimezone(dt.timezone(dt.timedelta(hours=9)))
    txn.append((t.date().isoformat(), r['partner_id'], r['currency'], Decimal(r['amount'])*(-1 if r['type']=='REFUND' else 1)))
unit={'USD':1,'EUR':1,'JPY':100,'CNY':1}
for src in range(4):
    res={}
    for d,p,c,a in txn:
        rt,_=rate(c+'KRW',d,src)
        k=(d,p); cnt,g=res.get(k,(0,0))
        res[k]=(cnt+1, g+int((a*rt/unit[c]).quantize(Decimal(1),ROUND_HALF_UP)))
    ok=[ (k,v[1],stmt[k][1]) for k,v in sorted(res.items()) if v[1]==stmt[k][1]]
    bad=[ (k,v[1],stmt[k][1]) for k,v in sorted(res.items()) if v[1]!=stmt[k][1]]
    print('src',src,'match',len(ok),'mismatch',len(bad))
    for b in bad: print('   ',b)
EOF
